const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');

const outputPaths = [
  path.join(process.cwd(), '学期小结.pdf'),
  path.join(process.cwd(), '张馨妍学期小结.pdf')
];
const macChrome = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const executablePath = fs.existsSync(macChrome) ? macChrome : undefined;

const essay = '这个学期，我比以前更懂得安排自己的生活。每天我会提醒自己按时起床、整理房间，也会主动帮家人做一些力所能及的事。遇到不开心的事，我能先冷静想一想，不再马上发脾气。不过我有时还不够耐心，做事容易着急。小学生活马上就要结束了，我希望自己在毕业前和以后都能更自律、更细心。';

const html = `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8" />
  <title>学期小结</title>
  <style>
    @page { size: A4; margin: 22mm 24mm; }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
      color: #222;
      background: #fff;
      line-height: 1.9;
    }
    .page {
      min-height: calc(297mm - 44mm);
      display: flex;
      flex-direction: column;
      align-items: center;
    }
    h1 {
      width: 100%;
      margin: 0 0 28px;
      text-align: center;
      font-size: 30px;
      font-weight: 700;
      letter-spacing: 4px;
    }
    .content {
      width: 100%;
      max-width: 680px;
      font-size: 20px;
      text-indent: 2em;
    }
  </style>
</head>
<body>
  <main class="page">
    <h1>学期小结</h1>
    <section class="content">${essay}</section>
  </main>
</body>
</html>`;

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'networkidle0' });
  for (const outputPath of outputPaths) {
    await page.pdf({ path: outputPath, format: 'A4', printBackground: true });
    console.log(`PDF generated: ${outputPath}`);
  }
  await browser.close();
})().catch((error) => {
  console.error(error);
  process.exit(1);
});
